"use strict";(self.webpackChunkenterprise_ai_agents_applied_ml_book=self.webpackChunkenterprise_ai_agents_applied_ml_book||[]).push([[9383],{7731(n,e,a){a.r(e),a.d(e,{assets:()=>d,contentTitle:()=>c,default:()=>g,frontMatter:()=>l,metadata:()=>i,toc:()=>p});const i=JSON.parse('{"id":"part5-deep-learning-and-llms/ffn-concepts","title":"Feed-Forward Neural Networks: Concepts and Intuition","description":"A practical tutorial built from the lecture transcript: why neural networks, how they compute, and how to train them (with PyTorch).","source":"@site/docs/part5-deep-learning-and-llms/01-ffn-concepts.mdx","sourceDirName":"part5-deep-learning-and-llms","slug":"/part5-deep-learning-and-llms/01-ffn-concepts","permalink":"/tutorials/part5-deep-learning-and-llms/01-ffn-concepts","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1785375762000,"sidebarPosition":1,"frontMatter":{"title":"Feed-Forward Neural Networks: Concepts and Intuition","slug":"/part5-deep-learning-and-llms/01-ffn-concepts","description":"A practical tutorial built from the lecture transcript: why neural networks, how they compute, and how to train them (with PyTorch).","sidebar_label":"1. Feed-forward network concepts","pagination_label":"1. Feed-forward network concepts","hide_title":true,"hide_table_of_contents":true},"sidebar":"bookSidebar","previous":{"title":"Part overview","permalink":"/tutorials/part5-deep-learning-and-llms/overview"},"next":{"title":"2. FFN training and debugging","permalink":"/tutorials/part5-deep-learning-and-llms/02-ffn-training-debugging"}}');var t=a(4848),o=a(8453),r=a(8172);const s=JSON.parse('{"sourcePath":"part5-deep-learning-and-llms/01-ffn-concepts.html","route":"/part5-deep-learning-and-llms/01-ffn-concepts","kind":"chapter","partId":"part5","partLabel":"Part V - Deep Learning & Large Language Models","accent":"coral","heading":"Feed-Forward Neural Networks (ANN FFN)","title":"Feed-Forward Neural Networks: Concepts and Intuition","description":"A practical tutorial built from the lecture transcript: why neural networks, how they compute, and how to train them (with PyTorch).","readingMinutes":7,"bodyClass":"","normalizeMath":false,"toc":[{"id":"1-start-with-why-and-how","label":"1) Start with \u201cWhy?\u201d and \u201cHow?\u201d"},{"id":"2-from-logistic-regression-to-a-neuron","label":"2) From logistic regression to a \u201cneuron\u201d"},{"id":"3-feed-forward-networks-architecture-and-forward-propagation","label":"3) Feed-forward networks: architecture & forward propagation"},{"id":"4-activation-functions-why-they-matter","label":"4) Activation functions (why they matter)"},{"id":"5-the-vanishing-gradient-problem-and-why-relu-helped","label":"5) The vanishing gradient problem (and why ReLU helped)"},{"id":"6-multiclass-classification-softmax-cross-entropy","label":"6) Multiclass classification: Softmax + Cross-Entropy"},{"id":"7-images-as-tensors-and-why-we-flatten-for-a-basic-ffn","label":"7) Images as tensors (and why we \u201cflatten\u201d for a basic FFN)"},{"id":"8-mnist-feed-forward-network-in-pytorch-with-mini-batches","label":"8) MNIST feed-forward network in PyTorch (with mini-batches)"},{"id":"sources-and-credits-plots-images-used","label":"Sources & credits (plots/images used)"}],"html":"<div class=\\"wrap\\">\\n    <header>\\n      \\n      <p>\\n        A practical tutorial built from the lecture transcript: <span class=\\"pill\\">why</span> neural networks,\\n        <span class=\\"pill\\">how</span> they compute, and <span class=\\"pill\\">how</span> to train them (with PyTorch).\\n      </p>\\n\\n      <div class=\\"chips\\">\\n        <span class=\\"chip\\">ANN \u2248 \u201cartificial neurons\u201d</span>\\n        <span class=\\"chip\\">FFN = feed-forward network</span>\\n        <span class=\\"chip\\">Forward propagation</span>\\n        <span class=\\"chip\\">Activations: sigmoid / tanh / ReLU</span>\\n        <span class=\\"chip\\">Softmax for multiclass</span>\\n        <span class=\\"chip\\">Mini-batch gradient descent</span>\\n        <span class=\\"chip\\">MNIST example</span>\\n      </div>\\n\\n      <nav>\\n        <a href=\\"#why\\">Why neural nets?</a>\\n        <a href=\\"#neuron\\">From a neuron to a network</a>\\n        <a href=\\"#forward\\">Forward propagation equations</a>\\n        <a href=\\"#activations\\">Activation functions</a>\\n        <a href=\\"#vanishing\\">Vanishing gradients</a>\\n        <a href=\\"#softmax\\">Softmax &amp; tasks</a>\\n        <a href=\\"#images\\">Images as tensors</a>\\n        <a href=\\"#mnist\\">MNIST FFN in PyTorch</a>\\n        <a href=\\"#credits\\">Sources &amp; credits</a>\\n      </nav>\\n    </header>\\n\\n    <section id=\\"why\\">\\n      <h2 id=\\"1-start-with-why-and-how\\">1) Start with \u201cWhy?\u201d and \u201cHow?\u201d</h2>\\n      <p>\\n        The motivation in the lecture is simple: the brain is a physical system of neurons that exchange signals.\\n        If a neuron can be approximated as a computation, then connecting many of them (in a simulation) might produce\\n        useful behavior\u2014what we call <b>artificial intelligence</b>.\\n      </p>\\n\\n      <div class=\\"callout\\">\\n        <p style=\\"margin:0;\\">\\n          <b>Key idea:</b> neural networks are powerful because they can learn <b>hierarchies of features</b>:\\n          simple patterns in early layers (edges), more meaningful parts in middle layers (eyes/noses), and full concepts later\\n          (faces). This \u201cstacking\u201d of representation is why the field is called <b>deep learning</b>.\\n        </p>\\n      </div>\\n\\n      <p>\\n        If you want an intuition playground, the lecture mentions TensorFlow Playground:\\n        <a href=\\"https://playground.tensorflow.org\\" target=\\"_blank\\" rel=\\"noopener\\">https://playground.tensorflow.org</a>\\n        (try changing layers/units and watch non-linear boundaries appear).\\n      </p>\\n    </section>\\n\\n    <section id=\\"neuron\\">\\n      <h2 id=\\"2-from-logistic-regression-to-a-neuron\\">2) From logistic regression to a \u201cneuron\u201d</h2>\\n      <p>\\n        A single artificial neuron is basically a linear model plus a nonlinearity. For an input vector \\\\(x \\\\in \\\\mathbb{R}^d\\\\):\\n      </p>\\n\\n      <p>\\n        \\\\[\\n          z = w^\\\\top x + b\\n        \\\\]\\n        \\\\[\\n          a = \\\\sigma(z)\\n        \\\\]\\n      </p>\\n\\n      <p class=\\"muted\\">\\n        Here \\\\(w\\\\) are weights, \\\\(b\\\\) is a bias, \\\\(z\\\\) is the pre-activation, and \\\\(a\\\\) is the activated output.\\n        In binary classification, \\\\(\\\\sigma\\\\) (sigmoid) turns \\\\(z\\\\) into a value in \\\\((0,1)\\\\), interpretable as a probability.\\n      </p>\\n\\n      <figure>\\n        <img alt=\\"Sigmoid function plot\\" src=\\"/tutorials/images/external/Sigmoid-function-baf8d0da10-fallback.svg\\">\\n        <figcaption>\\n          Sigmoid curve (Wikimedia Commons). Source page:\\n          <a href=\\"https://commons.wikimedia.org/wiki/File:Sigmoid-function.svg\\" target=\\"_blank\\" rel=\\"noopener\\">File:Sigmoid-function.svg</a>\\n        </figcaption>\\n      </figure>\\n    </section>\\n\\n    <section id=\\"forward\\">\\n      <h2 id=\\"3-feed-forward-networks-architecture-and-forward-propagation\\">3) Feed-forward networks: architecture &amp; forward propagation</h2>\\n\\n      <p>\\n        A <b>feed-forward</b> neural network arranges neurons in layers, with connections flowing from input \u2192 hidden layers \u2192 output.\\n        (If connections loop back to earlier layers, that\u2019s typically a <b>recurrent</b> design; the transcript contrasts these.)\\n      </p>\\n\\n      <h3 id=\\"vectorized-layer-equation\\">Vectorized layer equation</h3>\\n      <p>\\n        For layer \\\\(\\\\ell\\\\), we typically use:\\n      </p>\\n\\n      <p>\\n        \\\\[\\n          z^{(\\\\ell)} = W^{(\\\\ell)} a^{(\\\\ell-1)} + b^{(\\\\ell)}\\n        \\\\]\\n        \\\\[\\n          a^{(\\\\ell)} = g^{(\\\\ell)}\\\\!\\\\left(z^{(\\\\ell)}\\\\right)\\n        \\\\]\\n      </p>\\n\\n      <p class=\\"muted\\">\\n        This is the same idea as the single neuron, but generalized:\\n        \\\\(W^{(\\\\ell)}\\\\) is a matrix of weights, \\\\(b^{(\\\\ell)}\\\\) is a bias vector,\\n        and \\\\(g^{(\\\\ell)}\\\\) is an activation function applied elementwise (except for some output activations like softmax).\\n      </p>\\n\\n      <div class=\\"kpi\\">\\n        <div class=\\"card\\">\\n          <b>What changes vs. linear/logistic regression?</b>\\n          Nothing fundamental\u2014just multiple linear transforms chained with nonlinearities.\\n        </div>\\n        <div class=\\"card\\">\\n          <b>Why does that help?</b>\\n          Without nonlinearities, stacked linear layers collapse into a single linear layer.\\n        </div>\\n        <div class=\\"card\\">\\n          <b>How to read it?</b>\\n          Think \u201cfeature \u2192 feature \u2192 feature \u2192 \u2026 \u2192 final prediction\u201d.\\n        </div>\\n      </div>\\n\\n      <h3 id=\\"a-2-layer-example-hidden-layer-output-layer\\">A 2-layer example (hidden layer + output layer)</h3>\\n      <p>\\n        \\\\[\\n          a^{(1)} = g\\\\!\\\\left(W^{(1)}x + b^{(1)}\\\\right)\\n        \\\\]\\n        \\\\[\\n          \\\\hat{y} = \\\\text{(output activation)}\\\\!\\\\left(W^{(2)}a^{(1)} + b^{(2)}\\\\right)\\n        \\\\]\\n      </p>\\n    </section>\\n\\n    <section id=\\"activations\\">\\n      <h2 id=\\"4-activation-functions-why-they-matter\\">4) Activation functions (why they matter)</h2>\\n\\n      <p>\\n        The lecture emphasizes: activations are what give neural networks the ability to learn <b>non-linear</b> decision boundaries.\\n        Without them, you get only linear separators.\\n      </p>\\n\\n      <div class=\\"grid two\\">\\n        <div>\\n          <h3 id=\\"sigmoid\\">Sigmoid</h3>\\n          <p>\\n            \\\\[\\n              \\\\sigma(z)=\\\\frac{1}{1+e^{-z}}\\n            \\\\]\\n          </p>\\n          <p class=\\"muted\\">\\n            Good for binary outputs, but can be problematic in deep networks due to small derivatives.\\n          </p>\\n        </div>\\n        <div>\\n          <h3 id=\\"tanh-hyperbolic-tangent\\">Tanh (hyperbolic tangent)</h3>\\n          <p>\\n            \\\\[\\n              \\\\tanh(z)=\\\\frac{e^z-e^{-z}}{e^z+e^{-z}}\\n            \\\\]\\n          </p>\\n          <p class=\\"muted\\">\\n            Similar \u201cS-shape\u201d to sigmoid, but centered around 0 (outputs in \\\\((-1,1)\\\\)), which often helps internal scaling.\\n          </p>\\n        </div>\\n      </div>\\n\\n      <figure>\\n        <img alt=\\"Hyperbolic tangent plot\\" src=\\"/tutorials/images/external/Hyperbolic_Tangent-ad2a6621e1-fallback.svg\\">\\n        <figcaption>\\n          Tanh curve (Wikimedia Commons). Source page:\\n          <a href=\\"https://commons.wikimedia.org/wiki/File:Hyperbolic_Tangent.svg\\" target=\\"_blank\\" rel=\\"noopener\\">File:Hyperbolic_Tangent.svg</a>\\n        </figcaption>\\n      </figure>\\n\\n      <h3 id=\\"relu-rectified-linear-unit\\">ReLU (Rectified Linear Unit)</h3>\\n      <p>\\n        \\\\[\\n          \\\\mathrm{ReLU}(z)=\\\\max(0,z)\\n        \\\\]\\n      </p>\\n      <p class=\\"muted\\">\\n        The lecture\u2019s storyline: researchers moved from \u201cbeautiful smooth\u201d activations (sigmoid/tanh) toward ReLU\\n        because it trains deep networks more reliably in practice.\\n      </p>\\n\\n      <figure>\\n        <img alt=\\"ReLU activation function plot\\" src=\\"/tutorials/images/external/ReLU_Activation_Function_Plot-8781a45184-fallback.svg\\">\\n        <figcaption>\\n          ReLU \u201chockey stick\u201d (Wikimedia Commons). Source page:\\n          <a href=\\"https://en.wikipedia.org/wiki/Rectifier_(neural_networks)\\" target=\\"_blank\\" rel=\\"noopener\\">Rectifier (neural networks)</a>\\n          and image URL from upload.wikimedia.org.\\n        </figcaption>\\n      </figure>\\n\\n      <div class=\\"callout\\">\\n        <p style=\\"margin:0;\\">\\n          <b>Pragmatic ML takeaway (from the transcript):</b> experimentation beats philosophy.\\n          If you have a computer, run experiments instead of guessing outcomes in your head.\\n        </p>\\n      </div>\\n    </section>\\n\\n    <section id=\\"vanishing\\">\\n      <h2 id=\\"5-the-vanishing-gradient-problem-and-why-relu-helped\\">5) The vanishing gradient problem (and why ReLU helped)</h2>\\n\\n      <p>\\n        When training with backpropagation, gradients for earlier layers are products of many derivatives (chain rule).\\n        If these derivatives are often small, multiplying them repeatedly can make the gradient <b>shrink toward zero</b>\\n        for early layers\u2014so those layers barely learn.\\n      </p>\\n\\n      <h3 id=\\"sigmoid-derivative-is-small-most-of-the-time\\">Sigmoid derivative is small most of the time</h3>\\n      <p>\\n        \\\\[\\n          \\\\sigma\'(z)=\\\\sigma(z)\\\\bigl(1-\\\\sigma(z)\\\\bigr)\\n        \\\\]\\n      </p>\\n      <p>\\n        The derivative peaks at \\\\(0.25\\\\). Repeated multiplication like \\\\((0.25)^5 \\\\approx 0.0009766\\\\) shrinks fast.\\n      </p>\\n\\n      <figure>\\n        <img alt=\\"Sigmoid and its derivative\\" src=\\"/tutorials/images/external/Sigmoid-derivative-5a7e62a47b-fallback.svg\\">\\n        <figcaption>\\n          Sigmoid vs. sigmoid derivative (Wikimedia Commons). Source page:\\n          <a href=\\"https://commons.wikimedia.org/wiki/File:Sigmoid-derivative.png\\" target=\\"_blank\\" rel=\\"noopener\\">File:Sigmoid-derivative.png</a>\\n        </figcaption>\\n      </figure>\\n\\n      <h3 id=\\"a-related-visualization-used-in-discussions-of-vanishing-gradients\\">A related visualization used in discussions of vanishing gradients</h3>\\n      <figure>\\n        <img alt=\\"One-neuron recurrent network bifurcation diagram\\" src=\\"/tutorials/images/external/One-neuron_recurrent_network_bifurcation_diagram-c62882fbda-fallback.svg\\">\\n        <figcaption>\\n          Diagram referenced in vanishing-gradient discussions (Wikimedia Commons). Source page:\\n          <a href=\\"https://commons.wikimedia.org/wiki/File:One-neuron_recurrent_network_bifurcation_diagram.png\\" target=\\"_blank\\" rel=\\"noopener\\">\\n            File:One-neuron recurrent network bifurcation diagram.png\\n          </a>\\n        </figcaption>\\n      </figure>\\n\\n      <p class=\\"muted\\">\\n        Historically (as mentioned in the lecture), one workaround was layer-wise pretraining (e.g., Hinton\u2019s earlier-era approaches).\\n        Modern practice usually relies on better activations (ReLU-family), initialization, normalization, and optimizers.\\n      </p>\\n    </section>\\n\\n    <section id=\\"softmax\\">\\n      <h2 id=\\"6-multiclass-classification-softmax-cross-entropy\\">6) Multiclass classification: Softmax + Cross-Entropy</h2>\\n\\n      <p>\\n        For \\\\(K\\\\) classes, the output layer produces a vector of logits \\\\(z \\\\in \\\\mathbb{R}^K\\\\).\\n        We convert logits into a probability distribution with <b>softmax</b>:\\n      </p>\\n\\n      <p>\\n        \\\\[\\n          \\\\mathrm{softmax}(z)_i = \\\\frac{e^{z_i}}{\\\\sum_{j=1}^{K} e^{z_j}}\\n        \\\\]\\n      </p>\\n\\n      <p class=\\"muted\\">\\n        This guarantees probabilities are positive and sum to 1. In practice, we usually do not apply softmax explicitly during training;\\n        we use a numerically-stable loss that combines softmax with cross-entropy.\\n      </p>\\n\\n      <div class=\\"grid two\\">\\n        <figure>\\n          <img alt=\\"Softmax illustration\\" src=\\"/tutorials/images/external/Softmax-89e10495c2-fallback.svg\\">\\n          <figcaption>\\n            Softmax illustration (Wikimedia Commons). Source page:\\n            <a href=\\"https://commons.wikimedia.org/wiki/File:Softmax.svg\\" target=\\"_blank\\" rel=\\"noopener\\">File:Softmax.svg</a>\\n          </figcaption>\\n        </figure>\\n        <figure>\\n          <img alt=\\"Softmax illustration (English)\\" src=\\"/tutorials/images/external/Softmax_en-13b6657f61-fallback.svg\\">\\n          <figcaption>\\n            Softmax illustration (English) (Wikimedia Commons). Source page:\\n            <a href=\\"https://commons.wikimedia.org/wiki/File:Softmax_en.svg\\" target=\\"_blank\\" rel=\\"noopener\\">File:Softmax_en.svg</a>\\n          </figcaption>\\n        </figure>\\n      </div>\\n\\n      <h3 id=\\"three-common-tasks-output-activations\\">Three common tasks \u2194 output activations</h3>\\n      <ul>\\n        <li><b>Regression:</b> identity output (no activation): \\\\(\\\\hat{y}=z\\\\)</li>\\n        <li><b>Binary classification:</b> sigmoid output: \\\\(\\\\hat{y}=\\\\sigma(z)\\\\)</li>\\n        <li><b>Multiclass classification:</b> softmax output: \\\\(\\\\hat{y}=\\\\mathrm{softmax}(z)\\\\)</li>\\n      </ul>\\n\\n      <div class=\\"callout\\">\\n        <p style=\\"margin:0;\\">\\n          The lecture also notes: softmax can handle binary classification too (with \\\\(K=2\\\\)), but it\u2019s redundant because the two probabilities\\n          always sum to 1.\\n        </p>\\n      </div>\\n    </section>\\n\\n    <section id=\\"images\\">\\n      <h2 id=\\"7-images-as-tensors-and-why-we-flatten-for-a-basic-ffn\\">7) Images as tensors (and why we \u201cflatten\u201d for a basic FFN)</h2>\\n\\n      <p>\\n        Computers store images as arrays. A color image (RGB) is typically a tensor of shape:\\n      </p>\\n      <p>\\n        \\\\[\\n          \\\\text{image} \\\\in \\\\mathbb{R}^{H \\\\times W \\\\times C}, \\\\quad C=3\\n        \\\\]\\n      </p>\\n      <p>\\n        Each pixel channel is often quantized into 256 levels (0\u2013255). For neural networks, it\u2019s common to scale to \\\\([0,1]\\\\).\\n      </p>\\n\\n      <h3 id=\\"grayscale-is-simpler\\">Grayscale is simpler</h3>\\n      <p class=\\"muted\\">\\n        MNIST digits are grayscale, so each image is \\\\(28 \\\\times 28\\\\) (no RGB channels).\\n      </p>\\n\\n      <h3 id=\\"flattening\\">Flattening</h3>\\n      <p>\\n        A fully-connected FFN expects vectors. Flattening turns a \\\\(28\\\\times 28\\\\) image into a vector of length \\\\(784\\\\):\\n      </p>\\n      <p>\\n        \\\\[\\n          x \\\\in \\\\mathbb{R}^{28\\\\times 28} \\\\;\\\\;\\\\longrightarrow\\\\;\\\\; \\\\mathrm{vec}(x)\\\\in \\\\mathbb{R}^{784}\\n        \\\\]\\n      </p>\\n\\n      <div class=\\"grid two\\">\\n        <figure>\\n          <img alt=\\"MNIST samples\\" src=\\"/tutorials/images/external/MnistExamples-d4e8cf54a6.png\\">\\n          <figcaption>\\n            MNIST sample digits (Wikimedia Commons). Source page:\\n            <a href=\\"https://commons.wikimedia.org/wiki/File:MnistExamples.png\\" target=\\"_blank\\" rel=\\"noopener\\">File:MnistExamples.png</a>\\n          </figcaption>\\n        </figure>\\n\\n        <figure>\\n          <img alt=\\"t-SNE embedding of MNIST\\" src=\\"/tutorials/images/external/T-SNE_Embedding_of_MNIST-9dd0424557-fallback.svg\\">\\n          <figcaption>\\n            t-SNE embedding of MNIST (Wikimedia Commons). Source page:\\n            <a href=\\"https://commons.wikimedia.org/wiki/File:T-SNE_Embedding_of_MNIST.png\\" target=\\"_blank\\" rel=\\"noopener\\">\\n              File:T-SNE Embedding of MNIST.png\\n            </a>\\n          </figcaption>\\n        </figure>\\n      </div>\\n    </section>\\n\\n    <section id=\\"mnist\\">\\n      <h2 id=\\"8-mnist-feed-forward-network-in-pytorch-with-mini-batches\\">8) MNIST feed-forward network in PyTorch (with mini-batches)</h2>\\n\\n      <p>\\n        The lecture\u2019s example: MNIST has 10 classes (digits 0\u20139), so it\u2019s multiclass classification.\\n        A simple FFN can look like: <b>784 \u2192 128 \u2192 10</b>, with ReLU in the hidden layer.\\n      </p>\\n\\n      <h3 id=\\"model-equations-as-described\\">Model equations (as described)</h3>\\n      <p>\\n        \\\\[\\n          a^{(1)} = \\\\mathrm{ReLU}(W^{(1)}x + b^{(1)})\\n        \\\\]\\n        \\\\[\\n          z^{(2)} = W^{(2)}a^{(1)} + b^{(2)}\\n        \\\\]\\n        \\\\[\\n          \\\\hat{y} = \\\\mathrm{softmax}(z^{(2)}) \\\\quad \\\\text{(conceptually; training uses cross-entropy)}\\n        \\\\]\\n      </p>\\n\\n      <div class=\\"callout\\">\\n        <p style=\\"margin:0;\\">\\n          <b>Mini-batch gradient descent:</b> instead of computing gradients over the entire dataset at once,\\n          we compute them on small batches. PyTorch\u2019s <code>DataLoader</code> handles batching for you.\\n        </p>\\n      </div>\\n\\n      <h3 id=\\"pytorch-code-end-to-end\\">PyTorch code (end-to-end)</h3>\\n      <p class=\\"muted\\">\\n        This follows the transcript\u2019s steps: load MNIST, flatten + scale, build FFN, train with batches, evaluate, and inspect mistakes.\\n      </p>\\n\\n<pre><code class=\\"language-python\\">import torch\\nimport torch.nn as nn\\nimport torch.nn.functional as F\\nfrom torch.utils.data import DataLoader\\nfrom torchvision import datasets, transforms\\n\\n# 1) Data: MNIST (grayscale 28x28)\\n# - ToTensor() scales uint8 [0,255] -&gt; float [0,1]\\n# - We\'ll flatten in the training loop (or use transforms.Lambda)\\ntransform = transforms.ToTensor()\\n\\ntrain_ds = datasets.MNIST(root=\\"data\\", train=True, download=True, transform=transform)\\ntest_ds  = datasets.MNIST(root=\\"data\\", train=False, download=True, transform=transform)\\n\\ntrain_loader = DataLoader(train_ds, batch_size=128, shuffle=True, num_workers=2, pin_memory=True)\\ntest_loader  = DataLoader(test_ds, batch_size=256, shuffle=False, num_workers=2, pin_memory=True)\\n\\ndevice = torch.device(\\"cuda\\" if torch.cuda.is_available() else \\"cpu\\")\\n\\n\\n# 2) Model: 784 -&gt; 128 -&gt; 10\\nclass FFN(nn.Module):\\n    def __init__(self):\\n        super().__init__()\\n        self.fc1 = nn.Linear(28*28, 128)\\n        self.fc2 = nn.Linear(128, 10)\\n\\n    def forward(self, x):\\n        # x: (B, 1, 28, 28) -&gt; flatten to (B, 784)\\n        x = x.view(x.size(0), -1)\\n        x = F.relu(self.fc1(x))\\n        logits = self.fc2(x)  # raw scores (logits)\\n        return logits\\n\\nmodel = FFN().to(device)\\n\\n# 3) Training setup\\n# CrossEntropyLoss = LogSoftmax + NLLLoss (numerically stable)\\ncriterion = nn.CrossEntropyLoss()\\noptimizer = torch.optim.SGD(model.parameters(), lr=0.1)\\n\\ndef accuracy_from_logits(logits, y):\\n    preds = logits.argmax(dim=1)\\n    return (preds == y).float().mean().item()\\n\\n# 4) Train loop (mini-batch gradient descent)\\ndef train_one_epoch():\\n    model.train()\\n    total_loss = 0.0\\n    total_acc = 0.0\\n    n_batches = 0\\n\\n    for x, y in train_loader:\\n        x, y = x.to(device), y.to(device)\\n\\n        optimizer.zero_grad()\\n        logits = model(x)\\n        loss = criterion(logits, y)\\n        loss.backward()\\n        optimizer.step()\\n\\n        total_loss += loss.item()\\n        total_acc += accuracy_from_logits(logits, y)\\n        n_batches += 1\\n\\n    return total_loss / n_batches, total_acc / n_batches\\n\\n@torch.no_grad()\\ndef evaluate():\\n    model.eval()\\n    total_loss = 0.0\\n    total_acc = 0.0\\n    n_batches = 0\\n\\n    for x, y in test_loader:\\n        x, y = x.to(device), y.to(device)\\n        logits = model(x)\\n        loss = criterion(logits, y)\\n\\n        total_loss += loss.item()\\n        total_acc += accuracy_from_logits(logits, y)\\n        n_batches += 1\\n\\n    return total_loss / n_batches, total_acc / n_batches\\n\\n# 5) Run training\\nfor epoch in range(1, 6):\\n    tr_loss, tr_acc = train_one_epoch()\\n    te_loss, te_acc = evaluate()\\n    print(f\\"epoch {epoch:02d} | train loss {tr_loss:.4f} acc {tr_acc:.4f} | test loss {te_loss:.4f} acc {te_acc:.4f}\\")\\n\\n\\n# 6) Inspect mistakes (what the model gets wrong)\\n@torch.no_grad()\\ndef collect_mistakes(max_items=24):\\n    model.eval()\\n    mistakes = []\\n    for x, y in test_loader:\\n        x, y = x.to(device), y.to(device)\\n        logits = model(x)\\n        preds = logits.argmax(dim=1)\\n        wrong_mask = preds != y\\n        if wrong_mask.any():\\n            xw = x[wrong_mask].cpu()\\n            yw = y[wrong_mask].cpu()\\n            pw = preds[wrong_mask].cpu()\\n            for i in range(xw.size(0)):\\n                mistakes.append((xw[i], int(yw[i]), int(pw[i])))\\n                if len(mistakes) &gt;= max_items:\\n                    return mistakes\\n    return mistakes\\n\\nmistakes = collect_mistakes()\\nprint(\\"Collected mistakes:\\", len(mistakes))\\n</code></pre>\\n\\n      <h3 id=\\"plotting-training-curves\\">Plotting training curves</h3>\\n      <p class=\\"muted\\">\\n        You can compare your runs to standard learning-curve discussions and visualizations.\\n        For example, compare whether training loss decreases smoothly, validation loss follows it, or validation loss starts rising while training loss keeps falling.\\n        You can also log your own metrics and view them in TensorBoard, Weights &amp; Biases, or another dashboard.\\n      </p>\\n\\n      <div class=\\"callout\\">\\n        <p style=\\"margin:0;\\">\\n          <b>Common gotcha:</b> If you use <code>nn.CrossEntropyLoss()</code>, do <b>not</b> apply softmax in your model forward pass.\\n          Cross-entropy expects raw logits.\\n        </p>\\n      </div>\\n\\n      <div class=\\"callout\\">\\n        <p style=\\"margin:0;\\">\\n          <b>Probability nuance:</b> softmax outputs non-negative values that sum to 1, so they are convenient class probabilities.\\n          They are not automatically <i>well calibrated</i>. A model can be 99% confident and still be wrong. Calibration is a separate\\n          evaluation topic, usually checked with reliability diagrams, expected calibration error, or held-out validation data.\\n        </p>\\n      </div>\\n    </section>\\n\\n    <section id=\\"credits\\">\\n      <h2 id=\\"sources-and-credits-plots-images-used\\">Sources &amp; credits (plots/images used)</h2>\\n      <p class=\\"muted\\">\\n        All plots shown are served from local assets, with source credits retained where applicable.\\n      </p>\\n      <ul class=\\"small\\">\\n        <li>Sigmoid plot: <a href=\\"https://commons.wikimedia.org/wiki/File:Sigmoid-function.svg\\" target=\\"_blank\\" rel=\\"noopener\\">Wikimedia Commons \u2014 Sigmoid-function.svg</a></li>\\n        <li>Tanh plot: <a href=\\"https://commons.wikimedia.org/wiki/File:Hyperbolic_Tangent.svg\\" target=\\"_blank\\" rel=\\"noopener\\">Wikimedia Commons \u2014 Hyperbolic_Tangent.svg</a></li>\\n        <li>ReLU plot (via upload.wikimedia.org): <a href=\\"https://en.wikipedia.org/wiki/Rectifier_(neural_networks)\\" target=\\"_blank\\" rel=\\"noopener\\">Wikipedia \u2014 Rectifier (neural networks)</a></li>\\n        <li>Sigmoid derivative: <a href=\\"https://commons.wikimedia.org/wiki/File:Sigmoid-derivative.png\\" target=\\"_blank\\" rel=\\"noopener\\">Wikimedia Commons \u2014 Sigmoid-derivative.png</a></li>\\n        <li>Softmax illustrations: <a href=\\"https://commons.wikimedia.org/wiki/File:Softmax.svg\\" target=\\"_blank\\" rel=\\"noopener\\">Softmax.svg</a>,\\n            <a href=\\"https://commons.wikimedia.org/wiki/File:Softmax_en.svg\\" target=\\"_blank\\" rel=\\"noopener\\">Softmax_en.svg</a></li>\\n        <li>MNIST samples: <a href=\\"https://commons.wikimedia.org/wiki/File:MnistExamples.png\\" target=\\"_blank\\" rel=\\"noopener\\">MnistExamples.png</a></li>\\n        <li>t-SNE MNIST embedding: <a href=\\"https://commons.wikimedia.org/wiki/File:T-SNE_Embedding_of_MNIST.png\\" target=\\"_blank\\" rel=\\"noopener\\">T-SNE Embedding of MNIST.png</a></li>\\n        <li>Vanishing gradient related diagram: <a href=\\"https://commons.wikimedia.org/wiki/File:One-neuron_recurrent_network_bifurcation_diagram.png\\" target=\\"_blank\\" rel=\\"noopener\\">One-neuron recurrent network bifurcation diagram.png</a></li>\\n        <li>TensorFlow Playground (interactive): <a href=\\"https://playground.tensorflow.org\\" target=\\"_blank\\" rel=\\"noopener\\">playground.tensorflow.org</a></li>\\n      </ul>\\n\\n      <div class=\\"hr\\"></div>\\n      <p class=\\"muted small\\">\\n        Equations are rendered through the book\'s shared math layer; source\\n        credits remain attached to the visual assets above.\\n      </p>\\n    </section>\\n  </div>"}'),l={title:"Feed-Forward Neural Networks: Concepts and Intuition",slug:"/part5-deep-learning-and-llms/01-ffn-concepts",description:"A practical tutorial built from the lecture transcript: why neural networks, how they compute, and how to train them (with PyTorch).",sidebar_label:"1. Feed-forward network concepts",pagination_label:"1. Feed-forward network concepts",hide_title:!0,hide_table_of_contents:!0},c=void 0,d={},p=[];function m(n){return(0,t.jsx)(r.A,{content:s})}function g(n={}){const{wrapper:e}={...(0,o.R)(),...n.components};return e?(0,t.jsx)(e,{...n,children:(0,t.jsx)(m,{...n})}):m()}}}]);